type: "quiz"
lang: "javascript"
question: |
  لنتخذ قرارنا الأول! ما هي الرسالة التي ستُعرض لطلب فاطمة؟
code: |
  let orderStatus = "Preparing";
  let message;

  if (orderStatus === "Preparing") {
    message = "يقوم الشيف بتحضير طلبك!";
  } else if (orderStatus === "Out for Delivery") {
    message = "سائقنا، خالد، في طريقه إليك!";
  } else {
    message = "يرجى التواصل مع الدعم للمساعدة.";
  }

  console.log(message);
---
solution: 0
options:
  - "`يقوم الشيف بتحضير طلبك!`"
  - "`سائقنا، خالد، في طريقه إليك!`"
  - "`يرجى التواصل مع الدعم للمساعدة.`"
  - "`undefined`"
explanation: |
  شرط `if` وهو `orderStatus === "Preparing"` صحيح (true).

  يتم تنفيذ الشفرة الموجودة داخل تلك الكتلة، مما يضبط قيمة `message` على الخيار الأول، ثم يتم تخطي كتلتي `else if` و `else`.

type: "quiz"
lang: "javascript"
question: |
  حاولت وضع منطقنا البرمجي في دالة، لكن هناك خطأ ما. هل يمكنك اكتشافه؟
code: |
  function getOrderStatusMessage(status) {
    if (status = "Delivered") {
      return "تم توصيل طلبك. بالهناء والشفاء!";
    }
    return "طلبك لا يزال قيد التجهيز.";
  }

  let finalMessage = getOrderStatusMessage("Preparing");
  console.log(finalMessage);
---
solution: 2
options:
  - "تحتاج الدالة إلى `console.log` بداخلها."
  - "لا توجد جملة `else`."
  - "يستخدم شرط `if` علامة `=` واحدة بدلاً من `===`."
  - "الدالة ينقصها فاصلة منقوطة في نهايتها."
explanation: |
  علامة المساواة الواحدة (`=`) تُستخدم **للإسناد**، وليس للمقارنة. إنها تُسند القيمة `"Delivered"` إلى `status` ثم تُقيّم كـ `true`، مما يتسبب في إرجاع الرسالة الخاطئة.

  للتحقق من المساواة، يجب أن نستخدم `==` أو `===`.

type: "quiz"
lang: "javascript"
question: |
  لنتدرب على سيناريو مختلف. لدينا قائمة بدرجات الطلاب. ماذا ستطبع هذه الحلقة التكرارية في الطرفية؟
code: |
  let studentGrades = [95, 88, 45];

  for (let i = 0; i < studentGrades.length; i++) {
    let grade = studentGrades[i];
    if (grade >= 50) {
      console.log("ناجح");
    } else {
      console.log("راسب");
    }
  }
---
solution: 1
options:
  - "`ناجح` `راسب` `راسب`"
  - "`ناجح` `ناجح` `راسب`"
  - "`ناجح` `ناجح` `ناجح`"
  - "الشفرة ستسبب خطأ."
explanation: |
  تعمل الحلقة التكرارية ثلاث مرات:
  1. قيمة `grade` هي 95. `95 >= 50` صحيحة (true)، لذا تطبع "ناجح".
  2. قيمة `grade` هي 88. `88 >= 50` صحيحة (true)، لذا تطبع "ناجح".
  3. قيمة `grade` هي 45. `45 >= 50` خاطئة (false)، لذا تطبع "راسب".
